CREATE TABLE "HuntScope" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "agentIds" JSONB NOT NULL, "mode" TEXT NOT NULL DEFAULT 'OBSERVE', "revision" INTEGER NOT NULL DEFAULT 1, "learningWindow" INTEGER NOT NULL DEFAULT 100, "evaluationWindow" INTEGER NOT NULL DEFAULT 10, "maxActionsPerHour" INTEGER NOT NULL DEFAULT 4, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "HuntCase" ("id" TEXT NOT NULL PRIMARY KEY, "scopeId" TEXT NOT NULL, "summary" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'observing', "lastOrdinal" INTEGER NOT NULL DEFAULT 0, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE UNIQUE INDEX "HuntCase_scopeId_key" ON "HuntCase"("scopeId");
CREATE TABLE "HuntLink" ("id" TEXT NOT NULL PRIMARY KEY, "dedupeKey" TEXT NOT NULL, "caseId" TEXT NOT NULL, "eventId" TEXT NOT NULL, "requestId" TEXT, "source" TEXT NOT NULL, "target" TEXT NOT NULL, "relation" TEXT NOT NULL, "category" TEXT NOT NULL, "details" JSONB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "HuntLink_dedupeKey_key" ON "HuntLink"("dedupeKey");
CREATE INDEX "HuntLink_caseId_createdAt_idx" ON "HuntLink"("caseId", "createdAt");
CREATE TABLE "HuntCursor" ("id" TEXT NOT NULL PRIMARY KEY, "ordinal" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "BehaviorBaseline" ("id" TEXT NOT NULL PRIMARY KEY, "agentId" TEXT NOT NULL, "version" INTEGER NOT NULL, "requestIds" JSONB NOT NULL, "profile" JSONB NOT NULL, "learningWindow" INTEGER NOT NULL, "evaluationWindow" INTEGER NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "BehaviorBaseline_agentId_version_key" ON "BehaviorBaseline"("agentId", "version");
CREATE TABLE "AgentMessage" ("id" TEXT NOT NULL PRIMARY KEY, "requestId" TEXT NOT NULL, "senderId" TEXT NOT NULL, "senderSessionId" TEXT NOT NULL, "receiverId" TEXT NOT NULL, "scopeId" TEXT NOT NULL, "referenceRequestId" TEXT NOT NULL, "rootRequestId" TEXT NOT NULL, "sourceId" TEXT, "sourceTrust" TEXT NOT NULL, "content" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "receivedRequestId" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AgentMessage_requestId_key" ON "AgentMessage"("requestId");
CREATE TABLE "DeceptionDeployment" ("id" TEXT NOT NULL PRIMARY KEY, "scopeId" TEXT NOT NULL, "template" TEXT NOT NULL, "trapId" TEXT NOT NULL, "selectionReason" TEXT NOT NULL, "operator" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "cleanedAt" DATETIME);
CREATE TABLE "ResponsePlan" ("id" TEXT NOT NULL PRIMARY KEY, "dedupeKey" TEXT NOT NULL, "caseId" TEXT NOT NULL, "scopeId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "sessionId" TEXT NOT NULL, "credentialId" TEXT NOT NULL, "revision" INTEGER NOT NULL, "mode" TEXT NOT NULL, "action" TEXT NOT NULL, "evidenceIds" JSONB NOT NULL, "status" TEXT NOT NULL, "result" JSONB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" DATETIME NOT NULL, "executedAt" DATETIME);
CREATE UNIQUE INDEX "ResponsePlan_dedupeKey_key" ON "ResponsePlan"("dedupeKey");
CREATE INDEX "ResponsePlan_caseId_idx" ON "ResponsePlan"("caseId");
